function formatInTimezone(dateObj, timeZone, options) {
  return new Intl.DateTimeFormat('en-US', { timeZone, ...options }).format(dateObj);
}

const items = $input.all().map(i => i.json).filter(j => j && j.appointment_id && j.reminder_tier && ['CONFIRMED', 'RESCHEDULED'].includes(j.status));
const clinicName = $env.CLINIC_NAME || 'Apex Healthcare Clinic';
const clinicAddress = $env.CLINIC_ADDRESS || '';

const results = [];
for (const appt of items) {
  const tz = appt.timezone || $env.CLINIC_TIMEZONE || 'UTC';
  const startDt = new Date(appt.start_time);
  const dateStr = formatInTimezone(startDt, tz, { month: 'short', day: 'numeric', year: 'numeric', timeZone: tz });
  const timeStr = formatInTimezone(startDt, tz, { hour: '2-digit', minute: '2-digit', timeZone: tz });
  const appointmentTimeLocal = dateStr + ' at ' + timeStr + ' (' + tz + ')';

  let timeNotice = '';
  if (appt.reminder_tier === '3D') timeNotice = 'in approximately 3 days';
  else if (appt.reminder_tier === '1D') timeNotice = 'tomorrow';
  else if (appt.reminder_tier === '4H') timeNotice = 'in approximately 4 hours';
  else if (appt.reminder_tier === '1H') timeNotice = 'in approximately 1 hour';

  const addressPart = clinicAddress ? `, ${clinicAddress}` : '';

  results.push({
    json: {
      appointment_id: appt.appointment_id,
      reminder_tier: appt.reminder_tier,
      claimed_at: appt.claimed_at,
      phone: appt.phone,
      customer_name: appt.customer_name,
      doctor_name: appt.doctor_name || appt.doctor_id,
      doctor_id: appt.doctor_id,
      service: appt.service,
      start_time: appt.start_time,
      end_time: appt.end_time,
      timezone: tz,
      appointment_time_local: appointmentTimeLocal,
      time_notice: timeNotice,
      clinic_name: clinicName
    }
  });
}

return results;

const successfulItems = $input.all();
const formattedItems = $('Format_Reminder_Payload').all();
const results = [];

for (let i = 0; i < successfulItems.length; i++) {
  const item = successfulItems[i];
  const pairedIdx = item.pairedItem?.item !== undefined ? item.pairedItem.item : (typeof item.pairedItem === 'number' ? item.pairedItem : i);
  const original = (formattedItems[pairedIdx] && formattedItems[pairedIdx].json) ? formattedItems[pairedIdx].json : item.json;
  if (original && original.appointment_id && original.reminder_tier) {
    results.push({
      json: {
        appointment_id: original.appointment_id,
        reminder_tier: original.reminder_tier,
        claimed_at: original.claimed_at,
        phone: original.phone,
        customer_name: original.customer_name
      }
    });
  }
}
return results;
